def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Color 1 fills between the top two nested diagonal V motifs: the
    # two middle-row anchors and their outer endpoints bound the segment.
    for r in range(1,h-1):
        for c in range(1,w-2):
            if (grid[r][c-1]==2 and grid[r][c+1]==2 and
                grid[r-1][c]==2 and grid[r+1][c]==2):
                end=next((x for x in range(c+2,w) if grid[r][x]==2),None)
                if end is not None:
                    for x in range(c+2,end):
                        if grid[r][x]==0: out[r][x]=1
    # The second repeated motif has a short downward continuation.
    for r in range(h-3):
        for c in range(1,w-1):
            if (grid[r][c]==2 and grid[r+1][c-1]==2 and grid[r+1][c+1]==2
                    and grid[r+2][c]==2):
                out[r+3][c]=1
    return out
PY

