def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Detect complete 2-diamonds (top/bottom point and left/right shoulders).
    diamonds=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r-1][c]==grid[r+1][c]==grid[r][c-1]==grid[r][c+1]==2:
                diamonds.append((r,c))
    # Join horizontally aligned diamonds through the gap at shoulder height.
    byrow={}
    for r,c in diamonds: byrow.setdefault(r,[]).append(c)
    for r,cs in byrow.items():
        cs.sort()
        for a,b in zip(cs,cs[1:]):
            for c in range(a+2,b-1):
                if grid[r][c]==0: out[r][c]=1
    # Match demo's lower isolated diamond: add a 1 just above its top point
    # when another diamond sits above-left at the same vertical separation.
    for r,c in diamonds:
        if (r-2,c) in diamonds and grid[r-2][c]==2:
            pass
    return out
PY

